{
  "name": "opencode-firefox",
  "version": "0.1.2",
  "description": "OpenCode plugin that drives Firefox over WebDriver BiDi — attach to your real session or launch an isolated profile. No extension, no browser tooling.",
  "type": "module",
  "license": "MIT",
  "author": "Yuval Rimar",
  "packageManager": "pnpm@10.11.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/rimar/opencode-firefox.git"
  },
  "homepage": "https://github.com/rimar/opencode-firefox#readme",
  "bugs": {
    "url": "https://github.com/rimar/opencode-firefox/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "firefox",
    "webdriver-bidi",
    "bidi",
    "browser-automation",
    "ai-agent"
  ],
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test test/*.test.ts",
    "check": "pnpm typecheck && pnpm test"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.3.0",
    "@types/node": "^26.6.6",
    "typescript": "^7.0.2"
  }
}
